import { afterEach, describe, expect, it } from 'vitest';
import { refs } from '@/dom/addressing/refs.js';
import { scrollContainer } from './scroll.js';

/** Make a real div behave like a scrollable container (jsdom has no layout, so we define metrics). */
function scrollableDiv(scrollHeight: number, clientHeight: number): HTMLDivElement {
  const div = document.createElement('div');
  div.style.overflowY = 'scroll'; // getComputedStyle reads inline style in jsdom
  Object.defineProperty(div, 'scrollHeight', { configurable: true, value: scrollHeight });
  Object.defineProperty(div, 'clientHeight', { configurable: true, value: clientHeight });
  let top = 0;
  Object.defineProperty(div, 'scrollTop', {
    configurable: true,
    get: () => top,
    set: (v: number) => {
      top = Math.max(0, Math.min(v, scrollHeight - clientHeight));
    },
  });
  document.body.appendChild(div);
  return div;
}

describe('scrollContainer', () => {
  afterEach(() => {
    document.body.innerHTML = '';
  });

  it('1: scrolls the ref container ~a viewport and reports position (not yet at end)', () => {
    const div = scrollableDiv(1000, 200);
    const r = scrollContainer(refs.refFor(div), undefined);
    expect(r.scrolled).toBe(true);
    expect(r.scrollTop).toBe(160); // 200 * 0.8 default step
    expect(r.atEnd).toBe(false);
    expect(r.scrollHeight).toBe(1000);
  });

  it('2: an explicit dy is honored', () => {
    const div = scrollableDiv(1000, 200);
    const r = scrollContainer(refs.refFor(div), 500);
    expect(r.scrollTop).toBe(500);
  });

  it('3: scrolling near the bottom clamps and reports atEnd', () => {
    const div = scrollableDiv(1000, 200);
    const ref = refs.refFor(div);
    scrollContainer(ref, 700); // → 700
    const r = scrollContainer(ref, 700); // clamps to 800 (1000-200), at end
    expect(r.scrollTop).toBe(800);
    expect(r.atEnd).toBe(true);
  });

  it('4: a non-scrollable ref falls back to the document and returns the result shape', () => {
    const div = document.createElement('div');
    document.body.appendChild(div);
    const r = scrollContainer(refs.refFor(div), 100);
    expect(typeof r.scrollTop).toBe('number');
    expect(typeof r.atEnd).toBe('boolean');
    expect(typeof r.scrolled).toBe('boolean');
  });
});

import { describe, expect, it, beforeEach } from 'vitest';
import { ActionType } from '@reticlehq/core';
import { executeAction } from './actions.js';
import { refs } from '@/dom/addressing/refs.js';

/**
 * A drag whose target could not be resolved is a FAILED call, not a free drag.
 *
 * `drag` takes its drop target from `args.toRef` — and `toRef` appears **nowhere** in the tool
 * description an agent reads. The `args` sentence lists `value`, `text`, `native`, `holdMs` and
 * `confirmDangerous`, and never names the one argument without which the action cannot do its job.
 *
 * So the agent guesses, and `target` is the guess. Then:
 *
 *   - `asString(args['toRef'])` returns `''`;
 *   - `''` is read as "no target given", which is a legitimate free drag;
 *   - `dragElement(el, null)` runs a drag that lands nowhere, so no `drop` fires;
 *   - and it returns normally — `dispatched: true`, `domMutatedWithin: 2`, settled. **Success.**
 *
 * It reads as "drag dispatched and settled but never fired the app's onDrop", which invites the
 * wrong root cause — synthetic events not reaching handlers. The drag worked. It had nowhere to go.
 *
 * Two fixes, because either alone leaves the trap: accept the argument agents actually send, and
 * refuse when a target WAS named and could not be resolved. A free drag with no target named at all
 * stays legal, because that is a real thing to want.
 */
describe('drag refuses a target it cannot resolve', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
  });

  const pair = (): { a: HTMLElement; b: HTMLElement } => {
    document.body.innerHTML = '<div id="a">A</div><div id="b">B</div>';
    return {
      a: document.getElementById('a') as HTMLElement,
      b: document.getElementById('b') as HTMLElement,
    };
  };

  it('accepts `target`, which is what an agent with no documentation reaches for', async () => {
    const { a, b } = pair();
    let dropped = false;
    b.addEventListener('mouseup', () => {
      dropped = true;
    });
    await executeAction(refs.refFor(a), ActionType.DRAG, { target: refs.refFor(b) });
    expect(dropped, 'the drag must land on the element that was named').toBe(true);
  });

  it('still accepts `toRef`, the name the source has always read', async () => {
    const { a, b } = pair();
    let dropped = false;
    b.addEventListener('mouseup', () => {
      dropped = true;
    });
    await executeAction(refs.refFor(a), ActionType.DRAG, { toRef: refs.refFor(b) });
    expect(dropped).toBe(true);
  });

  it('REFUSES a named target that does not resolve, instead of dragging nowhere', async () => {
    // The false green. Previously this ran a target-less drag and reported success.
    const { a } = pair();
    await expect(
      executeAction(refs.refFor(a), ActionType.DRAG, { toRef: 'e999-does-not-exist' }),
    ).rejects.toThrow(/e999-does-not-exist/);
  });

  it('still allows a genuine free drag when no target is named at all', async () => {
    const { a } = pair();
    await expect(executeAction(refs.refFor(a), ActionType.DRAG, {})).resolves.toBeDefined();
  });
});

import { describe, it, expect } from 'vitest';
import { EventType } from '@reticlehq/core';
import { installDom } from '@/observers/dom.js';
import { executeAction, executeSequence } from './actions.js';
import { refs } from '@/dom/addressing/refs.js';

interface Collected {
  type: EventType;
  data: Record<string, unknown>;
}

/**
 * Airtight since-causality (settle). After ACT performs the action, executeAction awaits a
 * microtask + one animation frame ("settle") so React's commit (and the MutationObserver records
 * it triggers → dom.text/dom.attr events) flush BEFORE the command result resolves. That means
 * those events have t > since and appear in observe({ since }).
 */
describe('settle: act then observe exactly what it caused', () => {
  // Test A — an in-place text re-render after a click is captured (the dom.text case).
  it('captures an in-place text re-render after a click', async () => {
    document.body.innerHTML = '<button>Inc</button><span id="count">0</span>';
    const button = document.querySelector('button') as HTMLButtonElement;
    const span = document.getElementById('count') as HTMLSpanElement;

    const events: Collected[] = [];
    const teardown = installDom((type, data) => {
      events.push({ type, data });
    });
    // React-style commit-on-click: mutate text in place (characterData), not node replacement.
    button.addEventListener('click', () => {
      if (span.firstChild !== null) span.firstChild.nodeValue = '1';
    });

    try {
      await executeAction(refs.refFor(button), 'click', {});
    } finally {
      teardown();
    }

    const textEvents = events.filter((e) => e.type === EventType.DOM_TEXT);
    expect(textEvents).toHaveLength(1);
    expect(textEvents[0]?.data['text']).toBe('1');
    // It was an in-place re-render, not an add/remove of the count node.
    expect(events.some((e) => e.type === EventType.DOM_ADDED)).toBe(false);
    expect(events.some((e) => e.type === EventType.DOM_REMOVED)).toBe(false);
  });

  // Test C — the mutation event is emitted BEFORE the act promise resolves (causality proof).
  it('resolves the act only after the commit has been observed', async () => {
    document.body.innerHTML = '<button>Inc</button><span id="count">0</span>';
    const button = document.querySelector('button') as HTMLButtonElement;
    const span = document.getElementById('count') as HTMLSpanElement;

    const order: string[] = [];
    const teardown = installDom((type) => {
      if (type === EventType.DOM_TEXT) order.push('mutation');
    });
    button.addEventListener('click', () => {
      if (span.firstChild !== null) span.firstChild.nodeValue = '1';
    });

    try {
      await executeAction(refs.refFor(button), 'click', {});
      order.push('resolved');
    } finally {
      teardown();
    }

    expect(order.indexOf('mutation')).toBeGreaterThanOrEqual(0);
    expect(order.indexOf('mutation')).toBeLessThan(order.indexOf('resolved'));
  });

  // Test F — sequence settles between steps: React commits between clicks.
  it('settles between steps in a sequence', async () => {
    document.body.innerHTML = '<button>Inc</button><span id="count">0</span>';
    const button = document.querySelector('button') as HTMLButtonElement;
    const span = document.getElementById('count') as HTMLSpanElement;

    const values: string[] = [];
    const teardown = installDom((type, data) => {
      if (type === EventType.DOM_TEXT) values.push(String(data['text']));
    });
    button.addEventListener('click', () => {
      const node = span.firstChild;
      if (node !== null) node.nodeValue = String(Number(node.nodeValue ?? '0') + 1);
    });

    const ref = refs.refFor(button);
    try {
      await executeSequence([
        { ref, action: 'click' },
        { ref, action: 'click' },
      ]);
    } finally {
      teardown();
    }

    expect(values).toEqual(['1', '2']);
  });
});

/**
 * A drag has to carry coordinates, or it is a false green in Reticle's own tooling.
 *
 * Reported by an agent driving a `@dnd-kit/core` board: `reticle_act { action: "drag" }` returned
 * `ok:true`, `dispatched:true`, `effect.domMutatedWithin:0` — and the card had not moved. dnd-kit
 * resolves the `over` droppable from collision GEOMETRY, and every pointer event we dispatched was
 * built as `new PointerEvent(type, { bubbles, cancelable })`, so both source and target reported
 * `(0,0)`. Zero delta, so `onDragEnd` sees `over === source`, and the app is unchanged while the
 * tool reports success. That is the one failure mode this product exists to catch, produced by the
 * product.
 *
 * Three properties are needed and all three were missing:
 *
 *  - **coordinates**, so a geometry-based library can tell source from target at all;
 *  - **`buttons: 1` on the moves**, because the standard "was the mouse released?" guard is
 *    `event.buttons === 0` — a second reporter's drag-select bailed on exactly that;
 *  - **intermediate moves**, because `activationConstraint: { distance: N }` is the standard config
 *    for keeping a draggable card clickable, and one jump from A to B never crosses the threshold
 *    in a way the sensor observes.
 *
 * Also here: `press` set `key` and never `code`. dnd-kit's KeyboardSensor, react-aria and anything
 * keyed on physical keys match on `code`, so the keyboard fallback was unavailable too.
 */

import { describe, expect, it, beforeEach } from 'vitest';
import { dragElement } from './actions-dom.js';

interface Captured {
  type: string;
  clientX: number;
  clientY: number;
  buttons: number;
}

/** Place an element at a known box — jsdom reports zeros otherwise, which is the bug's disguise. */
function boxed(el: HTMLElement, x: number, y: number, w = 100, h = 40): HTMLElement {
  el.getBoundingClientRect = () =>
    ({ x, y, left: x, top: y, right: x + w, bottom: y + h, width: w, height: h }) as DOMRect;
  return el;
}

let source: HTMLElement;
let target: HTMLElement;
let seen: Captured[];

beforeEach(() => {
  document.body.innerHTML = '';
  source = boxed(document.createElement('div'), 0, 0);
  target = boxed(document.createElement('div'), 400, 200);
  document.body.append(source, target);
  seen = [];
  for (const type of [
    'pointerdown',
    'pointermove',
    'pointerup',
    'mousedown',
    'mousemove',
    'mouseup',
  ]) {
    document.addEventListener(type, (event) => {
      const e = event as PointerEvent;
      seen.push({ type: e.type, clientX: e.clientX, clientY: e.clientY, buttons: e.buttons });
    });
  }
});

const of = (type: string): Captured[] => seen.filter((e) => e.type === type);

describe('drag carries geometry', () => {
  it('starts at the source centre, not (0,0)', async () => {
    await dragElement(source, target, undefined);
    const down = of('pointerdown')[0];
    expect(down?.clientX).toBe(50);
    expect(down?.clientY).toBe(20);
  });

  it('ends at the target centre, so `over` can resolve to something else', async () => {
    await dragElement(source, target, undefined);
    const up = of('pointerup')[0];
    expect(up?.clientX).toBe(450);
    expect(up?.clientY).toBe(220);
  });

  it('emits intermediate moves, so a distance activationConstraint is satisfied', async () => {
    await dragElement(source, target, undefined);
    expect(of('pointermove').length).toBeGreaterThan(1);
  });

  it('advances monotonically from source to target', async () => {
    await dragElement(source, target, undefined);
    const xs = of('pointermove').map((e) => e.clientX);
    expect(xs).toEqual([...xs].sort((a, b) => a - b));
    expect(xs.at(-1)).toBe(450);
  });

  it('holds the primary button down through every move', async () => {
    await dragElement(source, target, undefined);
    // `event.buttons === 0` is the standard "mouse was released" guard; a move that reports 0 makes
    // a correct handler bail out mid-drag, which is indistinguishable from a broken fix.
    expect(of('pointermove').every((e) => 1 === e.buttons)).toBe(true);
    expect(of('mousemove').every((e) => 1 === e.buttons)).toBe(true);
  });

  it('releases the button on pointerup', async () => {
    await dragElement(source, target, undefined);
    expect(of('pointerup')[0]?.buttons).toBe(0);
  });

  it('a free drag with no target still moves within the source', async () => {
    await dragElement(source, null, undefined);
    expect(of('pointerdown')[0]?.clientX).toBe(50);
    expect(of('pointerup')[0]?.clientX).toBe(50);
  });
});

/**
 * A synthetic key press has to carry `code`, not only `key`.
 *
 * Reported by an agent whose keyboard fallback was unavailable: dnd-kit's `KeyboardSensor` matches
 * both its activation key and its arrow keys on `event.code`, so a press that sets only `key` can
 * neither start nor steer a keyboard drag. react-aria and anything keyed on PHYSICAL keys behave
 * the same way — `code` is the layout-independent identity of the key, and it is what a real
 * browser always sends.
 *
 * The failure is silent in the worst way: the event fires, the handler runs, and the guard simply
 * does not match — so the action reports dispatched and nothing happens.
 */

import { describe, expect, it, beforeEach } from 'vitest';
import { ActionType } from '@reticlehq/core';
import { executeAction } from './actions.js';
import { refs } from '@/dom/addressing/refs.js';

let el: HTMLButtonElement;
let seen: KeyboardEvent[];

beforeEach(() => {
  document.body.innerHTML = '';
  el = document.createElement('button');
  document.body.append(el);
  seen = [];
  for (const type of ['keydown', 'keyup']) {
    el.addEventListener(type, (event) => seen.push(event as KeyboardEvent));
  }
});

const press = async (args: Record<string, unknown>): Promise<void> => {
  await executeAction(refs.refFor(el), ActionType.PRESS, args);
};

describe('press carries a physical key code', () => {
  it('derives `code` for a letter', async () => {
    await press({ key: 'a' });
    expect(seen[0]?.key).toBe('a');
    expect(seen[0]?.code).toBe('KeyA');
  });

  it('derives `code` for a digit', async () => {
    await press({ key: '7' });
    expect(seen[0]?.code).toBe('Digit7');
  });

  it('passes named keys through unchanged — they are already codes', async () => {
    for (const key of ['Enter', 'Escape', 'Tab', 'ArrowDown']) {
      seen = [];
      await press({ key });
      expect(seen[0]?.code, key).toBe(key);
    }
  });

  it('names the space bar the way the spec does', async () => {
    await press({ key: ' ' });
    expect(seen[0]?.code).toBe('Space');
  });

  it('lets an explicit `code` win over the derived one', async () => {
    // A caller driving a non-US layout knows better than the derivation does.
    await press({ key: 'q', code: 'KeyA' });
    expect(seen[0]?.code).toBe('KeyA');
  });

  it('sets it on keyup too, so a held-key handler sees a matching pair', async () => {
    await press({ key: 'ArrowRight' });
    expect(seen.map((e) => e.type)).toEqual(['keydown', 'keyup']);
    expect(seen[1]?.code).toBe('ArrowRight');
  });

  it('leaves `code` empty rather than guessing at a multi-character mystery', async () => {
    await press({ key: 'Zzz' });
    expect(seen[0]?.code).toBe('');
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ActionType } from '@reticlehq/core';
import { executeAction } from './actions.js';
import { refs } from '@/dom/addressing/refs.js';

/**
 * The two claims the check/uncheck path rests on, pinned because both were once believed backwards.
 *
 * A proposed fix for the no-op false green set the checked property and fired `input`/`change` so a
 * framework tracker would notice. It fixed the desync and introduced a worse fault: an app that
 * autosaves, logs or POSTs on change now acts on an action that changed nothing. Caught by the first
 * test here, which is why the no-op branch dispatches nothing and reports `alreadyAtValue` instead.
 *
 * The second test settles the opposite question. The code this replaced insisted `dispatchEvent` does
 * not run activation behaviour, and used `el.click()` for that reason. It does run it — so cancellation
 * can be read off the event object, which survives a handler calling `stopPropagation()` where the old
 * window-level probe did not.
 */
function box(props: Partial<HTMLInputElement> = {}): HTMLInputElement {
  const el = document.createElement('input');
  el.type = 'checkbox';
  Object.assign(el, props);
  document.body.appendChild(el);
  return el;
}

describe('a no-op check must not fire an event no user produced', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
  });

  it('an app that autosaves on change does not save when nothing changed', async () => {
    const el = box({ checked: true });
    const save = vi.fn();
    el.addEventListener('change', save);

    await executeAction(refs.refFor(el), ActionType.CHECK, {});

    expect(el.checked).toBe(true);
    expect(save, 'a no-op check must not trigger the app’s change handler').not.toHaveBeenCalled();
  });

  it('a plain DOM listener sees no input event when the state did not move', async () => {
    // Framework-free on purpose: React's value tracker dedups a same-value write, so a React app can
    // hide this. A Vue, Svelte or vanilla listener cannot, and neither can an analytics hook.
    const el = box({ checked: true });
    const onInput = vi.fn();
    el.addEventListener('input', onInput);

    await executeAction(refs.refFor(el), ActionType.CHECK, {});

    expect(onInput).not.toHaveBeenCalled();
  });
});

describe('activation behaviour', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
  });

  it('a synthetic MouseEvent click toggles a checkbox', () => {
    const el = box({ checked: false });
    el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, composed: true }));
    expect(el.checked, 'if this is false, dispatchEvent does NOT run activation behaviour').toBe(
      true,
    );
  });
});

/**
 * A drag that never announces where the pointer went cannot drive drag-to-select.
 *
 * Reported on a plain-HTML data grid: `onMouseDown` on a cell sets the selection anchor,
 * `onMouseEnter` on other cells extends the selection while that anchor is set, and a window-level
 * `mouseup` clears it. The drag dispatched a real held-button `mousedown` and a stepped path of
 * moves, but never the boundary events a real pointer produces when it crosses from one element to
 * another, so React (which synthesises `onMouseEnter` from delegated `mouseover`/`mouseout`) never
 * called the extend handler and the selection never grew.
 */

import { describe, expect, it, beforeEach } from 'vitest';
import { dragElement } from './actions-dom.js';

interface Captured {
  type: string;
  buttons: number;
}

function boxed(el: HTMLElement, x: number, y: number, w = 100, h = 40): HTMLElement {
  el.getBoundingClientRect = () =>
    ({ x, y, left: x, top: y, right: x + w, bottom: y + h, width: w, height: h }) as DOMRect;
  return el;
}

function recorder(el: HTMLElement, log: Captured[]): void {
  for (const type of [
    'pointerdown',
    'mousedown',
    'pointerout',
    'mouseout',
    'pointerleave',
    'mouseleave',
    'pointerover',
    'mouseover',
    'pointerenter',
    'mouseenter',
    'pointermove',
    'mousemove',
    'pointerup',
    'mouseup',
  ]) {
    el.addEventListener(type, (e) => {
      log.push({ type, buttons: (e as MouseEvent).buttons });
    });
  }
}

describe('dragElement boundary events', () => {
  let source: HTMLElement;
  let dest: HTMLElement;
  let onSource: Captured[];
  let onDest: Captured[];

  beforeEach(() => {
    document.body.innerHTML = '';
    source = boxed(document.createElement('div'), 0, 0);
    dest = boxed(document.createElement('div'), 300, 0);
    document.body.append(source, dest);
    onSource = [];
    onDest = [];
    recorder(source, onSource);
    recorder(dest, onDest);
  });

  const seen = (log: Captured[], type: string): Captured[] => log.filter((c) => c.type === type);

  it('the source sees out/leave and the destination sees over/enter, button still held', async () => {
    await dragElement(source, dest, undefined);

    for (const type of ['pointerout', 'mouseout', 'pointerleave', 'mouseleave']) {
      const events = seen(onSource, type);
      expect(events, `source should see ${type}`).toHaveLength(1);
      expect(events[0]?.buttons).toBe(1);
    }
    for (const type of ['pointerover', 'mouseover', 'pointerenter', 'mouseenter']) {
      const events = seen(onDest, type);
      expect(events, `destination should see ${type}`).toHaveLength(1);
      expect(events[0]?.buttons).toBe(1);
    }
  });

  it('boundary events fire between mousedown and mouseup, in the crossing order', async () => {
    await dragElement(source, dest, undefined);

    const sourceOrder = onSource.map((c) => c.type);
    expect(sourceOrder.indexOf('mouseout')).toBeGreaterThan(sourceOrder.indexOf('mousedown'));
    const destOrder = onDest.map((c) => c.type);
    expect(destOrder.indexOf('mouseover')).toBeGreaterThan(-1);
    expect(destOrder.indexOf('mouseup')).toBeGreaterThan(destOrder.indexOf('mouseover'));
    // The enter pair arrives while the button is still held, not as part of release cleanup.
    expect(seen(onDest, 'mouseenter')[0]?.buttons).toBe(1);
    expect(seen(onDest, 'mouseup')[0]?.buttons).toBe(0);
  });

  it('a free drag (no target) crosses no boundary and fires no enter/leave pair', async () => {
    await dragElement(source, null, undefined);
    expect(seen(onSource, 'mouseenter')).toHaveLength(0);
    expect(seen(onSource, 'mouseleave')).toHaveLength(0);
    expect(seen(onSource, 'mousemove').length).toBeGreaterThan(0);
  });

  it('over/out bubble and enter/leave do not, matching what a real pointer emits', async () => {
    const bubbles: Record<string, boolean> = {};
    const watch = (el: HTMLElement): void => {
      for (const type of ['mouseover', 'mouseout', 'mouseenter', 'mouseleave']) {
        el.addEventListener(type, (e) => {
          bubbles[type] = e.bubbles;
        });
      }
    };
    watch(source);
    watch(dest);
    await dragElement(source, dest, undefined);
    expect(bubbles['mouseover']).toBe(true);
    expect(bubbles['mouseout']).toBe(true);
    expect(bubbles['mouseenter']).toBe(false);
    expect(bubbles['mouseleave']).toBe(false);
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

// executeAction must separate dispatch from settle. A settle that never lands a real frame
// (throttled/background tab where rAF never fires) must NOT reject and must NOT hang — it resolves
// with dispatched:true, settled:false, settleReason:'timeout'. A real dispatch failure still rejects.

describe('settle is bounded — never hangs on a throttled rAF', () => {
  beforeEach(() => {
    vi.resetModules();
    document.body.innerHTML = '';
  });
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('resolves executeAction(click) with dispatched:true, settled:false when rAF never fires', async () => {
    // rAF that NEVER invokes its callback — the background-tab failure mode.
    vi.stubGlobal('requestAnimationFrame', (_cb: FrameRequestCallback): number => 1);
    // Re-import so native-timers captures the stubbed rAF at module load.
    const { executeAction } = await import('./actions.js');
    const { refs } = await import('@/dom/addressing/refs.js');

    document.body.innerHTML = '<button>Save</button>';
    const el = document.querySelector('button');
    if (null === el) throw new Error('no button');
    const ref = refs.refFor(el);

    const r = await executeAction(ref, 'click'); // must RESOLVE, not reject/hang

    expect(r.dispatched).toBe(true);
    expect(r.effect.dispatched).toBe(true);
    expect(r.settled).toBe(false);
    // `settleReason: 'timeout'` IS the bound, stated by the code rather than measured off the
    // machine. The wall-clock assertion that used to sit here added no coverage these four lines
    // did not already have, and one load-dependent way to fail. The timeout below catches a genuine
    // hang. It was 5000, which the action's own settle bound plus a module re-import could exceed on
    // a loaded Windows runner (five timeouts there, code correct); 20s still fails a real hang.
    expect(r.settleReason).toBe('timeout');
  }, 20_000);

  it('still rejects on a stale ref even when rAF never fires', async () => {
    vi.stubGlobal('requestAnimationFrame', (): number => 1);
    const { executeAction } = await import('./actions.js');
    const { refs } = await import('@/dom/addressing/refs.js');
    document.body.innerHTML = '<button>gone</button>';
    const el = document.querySelector('button');
    if (null === el) throw new Error('no button');
    const ref = refs.refFor(el);
    document.body.innerHTML = ''; // detach → requireElement throws
    await expect(executeAction(ref, 'click')).rejects.toThrow();
  }, 20_000);

  it('surfaces per-step settled:false in executeSequence when rAF never fires', async () => {
    vi.stubGlobal('requestAnimationFrame', (_cb: FrameRequestCallback): number => 1);
    const { executeSequence } = await import('./actions.js');
    const { refs } = await import('@/dom/addressing/refs.js');

    document.body.innerHTML = '<button id="a">A</button><button id="b">B</button>';
    const a = document.querySelector('#a');
    const b = document.querySelector('#b');
    if (null === a || null === b) throw new Error('missing buttons');
    const refA = refs.refFor(a);
    const refB = refs.refFor(b);

    const res = await executeSequence([
      { ref: refA, action: 'click' },
      { ref: refB, action: 'click' },
    ]);

    expect(res.ok).toBe(true);
    expect(res.count).toBe(2);
    expect(res.effects.every((e) => true === e.dispatched)).toBe(true);
    expect(res.steps.every((s) => true === s.dispatched)).toBe(true);
    expect(res.steps.every((s) => false === s.settled)).toBe(true);
    expect(res.steps.every((s) => 'timeout' === s.settleReason)).toBe(true);
  }, 20_000);
});

/**
 * Teardown must obey the same rule install does: one observer failing may never stop the others.
 *
 * Install wraps each observer in `guard()`. Teardown ran bare, so ONE throwing disposer left every
 * later one unrun — `fetch`, XHR, `Storage.prototype.*`, `console` and the native dialogs stayed
 * patched forever on a page the SDK had been told to leave.
 */
import { describe, expect, it } from 'vitest';
import { EventType } from '@reticlehq/core';
import { runTeardowns } from './install-all.js';
import { SdkSite } from './sdk-failure.js';
import type { Emit } from './types.js';

describe('runTeardowns', () => {
  it('runs every teardown even when an earlier one throws', () => {
    const ran: string[] = [];
    const events: Array<{ type: EventType; data: Record<string, unknown> }> = [];
    const emit: Emit = (type, data) => {
      events.push({ type, data });
    };

    runTeardowns(emit, [
      () => ran.push('first'),
      () => {
        throw new Error('disposer exploded');
      },
      () => ran.push('third'),
    ]);

    expect(ran).toEqual(['first', 'third']);
    expect(events).toHaveLength(1);
    expect(events[0]?.type).toBe(EventType.SDK_FAILED);
    expect(events[0]?.data['site']).toBe(SdkSite.TEARDOWN);
    expect(events[0]?.data['message']).toBe('disposer exploded');
  });

  it('does not throw when the failure report itself cannot be sent', () => {
    expect(() =>
      runTeardowns(() => {
        throw new Error('emit is dead too');
      }, [
        () => {
          throw new Error('disposer exploded');
        },
      ]),
    ).not.toThrow();
  });
});

// @vitest-environment jsdom
import { describe, expect, it } from 'vitest';
import { ActionType } from '@reticlehq/core';
import { executeAction } from './actions.js';
import { refs } from '@/dom/addressing/refs.js';

/**
 * `press Escape` inside a modal `<dialog>` closes it the way a keyboard does (#1123).
 *
 * A dispatched key is untrusted and gets no default action, so the dialog's close request never ran:
 * no `cancel`, no `close`, and an app that closes through `onCancel` looked broken. jsdom has no
 * `showModal()`, `:modal` or `close()`, so the fixture supplies the modal state and the engine
 * methods a browser has, and the tests pin what Reticle does with them.
 */
function modalDialog(opts: { requestClose: boolean; modal?: boolean }): {
  dialog: HTMLDialogElement;
  button: HTMLButtonElement;
  seen: string[];
} {
  document.body.innerHTML = '<dialog open><button>Keep editing</button></dialog>';
  const dialog = document.querySelector('dialog') as HTMLDialogElement;
  const button = document.querySelector('button') as HTMLButtonElement;
  const seen: string[] = [];
  const modal = opts.modal ?? true;
  const matches = dialog.matches.bind(dialog);
  dialog.matches = (selector: string) => (':modal' === selector ? modal : matches(selector));
  const close = (): void => {
    dialog.removeAttribute('open');
    seen.push('close');
  };
  dialog.close = close;
  dialog.addEventListener('cancel', () => seen.push('cancel'));
  if (opts.requestClose) {
    // What a browser's requestClose does: a cancelable `cancel`, then close unless it was prevented.
    dialog.requestClose = () => {
      if (dialog.dispatchEvent(new Event('cancel', { cancelable: true }))) close();
    };
  } else {
    Object.defineProperty(dialog, 'requestClose', { value: undefined });
  }
  return { dialog, button, seen };
}

const escape = async (el: HTMLElement): Promise<unknown> =>
  executeAction(refs.refFor(el), ActionType.PRESS, { key: 'Escape' });

describe.each([
  ['with requestClose', true],
  ['without requestClose', false],
])('Escape in a modal dialog, %s', (_label, requestClose) => {
  it('fires cancel and closes the dialog', async () => {
    const { dialog, button, seen } = modalDialog({ requestClose });

    await escape(button);

    expect(seen).toEqual(['cancel', 'close']);
    expect(dialog.open).toBe(false);
  });

  it('leaves it open when the app prevents cancel', async () => {
    const { dialog, button, seen } = modalDialog({ requestClose });
    dialog.addEventListener('cancel', (event) => event.preventDefault());

    await escape(button);

    expect(seen).toEqual(['cancel']);
    expect(dialog.open).toBe(true);
  });
});

describe('Escape is left alone where a browser would not close anything', () => {
  it('a keydown the app prevented does not reach the dialog', async () => {
    const { dialog, button, seen } = modalDialog({ requestClose: true });
    button.addEventListener('keydown', (event) => event.preventDefault());

    await escape(button);

    expect(seen).toEqual([]);
    expect(dialog.open).toBe(true);
  });

  it('a non-modal open dialog has no close request on Escape', async () => {
    const { dialog, button, seen } = modalDialog({ requestClose: true, modal: false });

    await escape(button);

    expect(seen).toEqual([]);
    expect(dialog.open).toBe(true);
  });

  it('another key does nothing to the dialog', async () => {
    const { dialog, button, seen } = modalDialog({ requestClose: true });

    await executeAction(refs.refFor(button), ActionType.PRESS, { key: 'Tab' });

    expect(seen).toEqual([]);
    expect(dialog.open).toBe(true);
  });
});

describe('every way to press Escape reaches the dialog the same way', () => {
  it('as a chord, keys: ["Escape"]', async () => {
    const { dialog, button, seen } = modalDialog({ requestClose: true });

    await executeAction(refs.refFor(button), ActionType.PRESS, { keys: ['Escape'] });

    expect(seen).toEqual(['cancel', 'close']);
    expect(dialog.open).toBe(false);
  });

  it('held: the dialog closes on the first keydown, before the repeats', async () => {
    const { dialog, button } = modalDialog({ requestClose: true });
    const openAtEachKeydown: boolean[] = [];
    button.addEventListener('keydown', () => openAtEachKeydown.push(dialog.open));

    await executeAction(refs.refFor(button), ActionType.PRESS, { key: 'Escape', holdMs: 120 });

    expect(openAtEachKeydown.length).toBeGreaterThan(1);
    expect(openAtEachKeydown[0], 'the first keydown sees the dialog still open').toBe(true);
    expect(openAtEachKeydown.slice(1), 'the repeats run against a closed dialog').not.toContain(
      true,
    );
  });

  it('from a non-modal dialog nested inside the modal one', async () => {
    const { dialog, seen } = modalDialog({ requestClose: true });
    const inner = document.createElement('dialog');
    inner.setAttribute('open', '');
    const field = document.createElement('button');
    field.textContent = 'Inner';
    inner.append(field);
    dialog.append(inner);

    await escape(field);

    expect(seen).toEqual(['cancel', 'close']);
    expect(dialog.open).toBe(false);
  });
});

import { beforeEach, describe, expect, it } from 'vitest';
import { ActionType } from '@reticlehq/core';
import { executeAction } from './actions.js';
import { refs } from '@/dom/addressing/refs.js';

let el: HTMLInputElement;

beforeEach(() => {
  document.body.innerHTML = '';
  el = document.createElement('input');
  document.body.append(el);
});

const press = async (args: Record<string, unknown>): Promise<void> => {
  await executeAction(refs.refFor(el), ActionType.PRESS, args);
};

const recordTypes = (): string[] => {
  const seen: string[] = [];
  for (const type of ['keydown', 'keypress', 'keyup'] as const) {
    el.addEventListener(type, (event) => seen.push(`${event.type}:${event.key}`));
  }
  return seen;
};

describe('press dispatches browser-like keypress events', () => {
  it('fires keydown -> keypress -> keyup for a character key', async () => {
    const seen = recordTypes();
    await press({ key: '9' });
    expect(seen).toEqual(['keydown:9', 'keypress:9', 'keyup:9']);
  });

  it('fires keypress for Enter', async () => {
    const seen = recordTypes();
    await press({ key: 'Enter' });
    expect(seen).toEqual(['keydown:Enter', 'keypress:Enter', 'keyup:Enter']);
  });

  it.each(['Escape', 'Tab', 'ArrowLeft', 'Shift'])('does not fire keypress for %s', async (key) => {
    const seen = recordTypes();
    await press({ key });
    expect(seen).toEqual([`keydown:${key}`, `keyup:${key}`]);
  });

  it('does not fire keypress when keydown is cancelled', async () => {
    const seen = recordTypes();
    el.addEventListener('keydown', (event) => event.preventDefault());
    await press({ key: '9' });
    expect(seen).toEqual(['keydown:9', 'keyup:9']);
  });

  it('carries code and modifier state onto keypress', async () => {
    const seen: KeyboardEvent[] = [];
    el.addEventListener('keypress', (event) => seen.push(event));
    await press({ key: 'A', code: 'KeyA', modifiers: ['Shift'] });
    expect(seen).toHaveLength(1);
    expect(seen[0]?.code).toBe('KeyA');
    expect(seen[0]?.shiftKey).toBe(true);
  });

  it('fires keypress for character keys in the multi-key path', async () => {
    const seen = recordTypes();
    await press({ keys: ['a', 'b'] });
    expect(seen).toEqual([
      'keydown:a',
      'keypress:a',
      'keydown:b',
      'keypress:b',
      'keyup:b',
      'keyup:a',
    ]);
  });

  it('suppresses combo keypress when that keydown is cancelled', async () => {
    const seen = recordTypes();
    el.addEventListener('keydown', (event) => {
      if ('b' === event.key) event.preventDefault();
    });
    await press({ keys: ['a', 'b'] });
    expect(seen).toEqual(['keydown:a', 'keypress:a', 'keydown:b', 'keyup:b', 'keyup:a']);
  });

  it.each([
    ['9', 57],
    ['a', 97],
    ['A', 65],
    ['Enter', 13],
  ])('gives keypress for %s the legacy codes a scanner listener reads', async (key, code) => {
    // Barcode-scanner and POS handlers still read `which` / `keyCode` / `charCode` on keypress. A
    // synthetic event leaves all three at 0, so the scan arrives as a run of NULs.
    const seen: KeyboardEvent[] = [];
    el.addEventListener('keypress', (event) => seen.push(event));
    await press({ key });
    expect(seen).toHaveLength(1);
    expect([seen[0]?.keyCode, seen[0]?.charCode, seen[0]?.which]).toEqual([code, code, code]);
  });

  it('marks held-key keypress repeats as repeat events', async () => {
    const repeats: KeyboardEvent[] = [];
    el.addEventListener('keypress', (event) => {
      if (event.repeat) repeats.push(event);
    });
    await press({ key: '9', holdMs: 20 });
    expect(repeats.length).toBeGreaterThan(0);
    expect(repeats.every((event) => '9' === event.key)).toBe(true);
  });
});

/**
 * A whole view that rendered is not a message the app said.
 *
 * `appeared` earns its keep on small text: "Invalid credentials" turns a login that reports
 * `ok / settled / mutated` into one that says what went wrong. But an added node's `textContent`
 * flattens its ENTIRE subtree with no separators, so when a navigation swaps a view the field
 * becomes a page dump run together into one unreadable string.
 *
 * Measured on a real drive against the bench app, clicking Compose:
 *
 *   appeared: "Compose | generate a release note | DraftRelease note generatorTitle · commits on
 *              blurWhat shipped?GenerateOutputYour generated note appears here."
 *
 * 146 bytes, 36 tokens, on every navigation verdict, and no reader can act on any of it — note
 * "DraftRelease" and "blurWhat", which are two fragments with the boundary lost. The snapshot
 * already describes the new view properly, which makes dropping this the cheaper mistake, exactly
 * as it is for the bare-numeral case above.
 */

import { describe, expect, it } from 'vitest';
import { AppearedText } from './appeared-text.js';

const added = (el: Element): MutationRecord =>
  ({ type: 'childList', addedNodes: [el], target: document.body }) as unknown as MutationRecord;

const el = (html: string): Element => {
  const host = document.createElement('div');
  host.innerHTML = html;
  return host.firstElementChild ?? host;
};

describe('a rendered view is not something the app said', () => {
  it('drops a container whose subtree is a composed view', () => {
    const view = el(
      '<section><h1>Release note generator</h1><label>Title</label><input/>' +
        '<label>What shipped?</label><button>Generate</button><h2>Output</h2>' +
        '<p>Your generated note appears here.</p></section>',
    );
    const appeared = new AppearedText();
    appeared.collect([added(view)]);
    expect(appeared.effect().appeared).toBeUndefined();
  });

  it('keeps a message, even wrapped in an element', () => {
    // The whole reason the field exists — this must survive the cut.
    const appeared = new AppearedText();
    appeared.collect([added(el('<div class="error">Invalid credentials</div>'))]);
    expect(appeared.effect().appeared).toBe('Invalid credentials');
  });

  it('keeps a message with a little markup inside it', () => {
    const appeared = new AppearedText();
    appeared.collect([added(el('<div>Could not save — <strong>try again</strong></div>'))]);
    expect(appeared.effect().appeared).toContain('Could not save');
  });
});

/** Regression for #995: synthetic input must carry the target document's window. */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { ActionType } from '@reticlehq/core';
import { refs } from '@/dom/addressing/refs.js';
import { executeAction } from './actions.js';
import {
  dragElement,
  fireClickSequence,
  firePointer,
  firePointerNonBubbling,
  fireTapSequence,
} from './actions-dom.js';

const CLICK_EVENTS = ['pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'];
function capture(element: Element, types: readonly string[]): MouseEvent[] {
  const events: MouseEvent[] = [];
  for (const type of types)
    element.addEventListener(type, (event) => events.push(event as MouseEvent));
  return events;
}
beforeEach(() => {
  document.body.innerHTML = '';
});
afterEach(() => {
  vi.unstubAllGlobals();
});

describe('synthetic mouse and pointer input has the correct view', () => {
  it('supplies a window through the complete click sequence', async () => {
    const button = document.createElement('button');
    document.body.append(button);
    const events = capture(button, CLICK_EVENTS);
    await fireClickSequence(button);
    expect(events.map((event) => event.type)).toEqual(CLICK_EVENTS);
    expect(events.map((event) => event.view)).toEqual(CLICK_EVENTS.map(() => window));
  });
  it('uses an iframe target window rather than the global window', async () => {
    const frame = document.createElement('iframe');
    document.body.append(frame);
    const doc = frame.contentDocument;
    if (null === doc) throw new Error('test iframe has no document');
    const button = doc.createElement('button');
    doc.body.append(button);
    const events = capture(button, CLICK_EVENTS);
    await fireClickSequence(button);
    expect(events).toHaveLength(CLICK_EVENTS.length);
    for (const event of events) expect(event.view).toBe(doc.defaultView);
    expect(doc.defaultView).not.toBe(window);
  });

  it.each([false, true])('preserves view with PointerEvent available: %s', (available) => {
    vi.stubGlobal('PointerEvent', available ? MouseEvent : undefined);
    const button = document.createElement('button');
    const events = capture(button, ['pointerover', 'pointerenter']);
    firePointer(button, 'pointerover');
    firePointerNonBubbling(button, 'pointerenter');
    expect(events.map((event) => event.view)).toEqual([window, window]);
    expect(events.map((event) => event.bubbles)).toEqual([true, false]);
  });
  it('keeps touch pointer input and its compatibility click in the target window', async () => {
    const button = document.createElement('button');
    document.body.append(button);
    const events = capture(button, ['pointerdown', 'pointerup', 'click']);
    await fireTapSequence(button, undefined);
    expect(events.map((event) => event.view)).toEqual([window, window, window]);
  });

  it.each([ActionType.HOVER, ActionType.DBLCLICK, ActionType.CHECK, ActionType.UNCHECK])(
    'supplies view for %s dispatched through executeAction',
    async (action) => {
      const input = document.createElement('input');
      input.type = 'checkbox';
      input.checked = action === ActionType.UNCHECK;
      document.body.append(input);
      const events = capture(input, [
        'pointerover',
        'pointerenter',
        'pointermove',
        'mouseover',
        'mouseenter',
        'mousemove',
        'dblclick',
        'click',
      ]);
      await executeAction(refs.refFor(input), action, {});
      expect(events.length).toBeGreaterThan(0);
      for (const event of events) expect(event.view).toBe(window);
    },
  );
  it('lets a drag handler attach move and release listeners through event.view', async () => {
    const source = document.createElement('div');
    const target = document.createElement('div');
    document.body.append(source, target);
    const events = capture(source, ['pointerdown', 'mousedown']);
    const moves = vi.fn();
    const releases = vi.fn();
    source.addEventListener('mousedown', (event) => {
      event.view?.addEventListener('mousemove', moves);
      event.view?.addEventListener('mouseup', releases);
    });
    try {
      await dragElement(source, target, undefined);
      expect(events.map((event) => event.view)).toEqual([window, window]);
      expect(moves).toHaveBeenCalled();
      expect(releases).toHaveBeenCalledOnce();
      const move = moves.mock.calls[0]?.[0] as MouseEvent | undefined;
      expect(move?.view).toBe(window);
    } finally {
      window.removeEventListener('mousemove', moves);
      window.removeEventListener('mouseup', releases);
    }
  });
});

it('preserves a null view for an element in a detached document', async () => {
  const doc = document.implementation.createHTMLDocument('Detached');
  const button = doc.createElement('button');
  doc.body.append(button);
  const events = capture(button, CLICK_EVENTS);
  await fireClickSequence(button);
  expect(doc.defaultView).toBeNull();
  expect(events).toHaveLength(CLICK_EVENTS.length);
  for (const event of events) expect(event.view).toBeNull();
});

// #1003: a canvas or SVG app hit-tests from clientX/Y and reads pointerId/isPrimary; a click at
// (0,0) with no pointer id landed on nothing.
describe('a synthetic click says where it is and which pointer', () => {
  it('carries the target centre, a primary pointer id and the held button', async () => {
    const canvas = document.createElement('canvas');
    document.body.append(canvas);
    canvas.getBoundingClientRect = () => new DOMRect(10, 20, 100, 40);
    const events = capture(canvas, CLICK_EVENTS);
    await fireClickSequence(canvas);
    for (const event of events) expect([event.clientX, event.clientY]).toEqual([60, 40]);
    expect(events.find((e) => 'mousedown' === e.type)?.buttons).toBe(1);
    expect(events.find((e) => 'mouseup' === e.type)?.buttons).toBe(0);
    const down = events.find((e) => 'pointerdown' === e.type) as MouseEvent & {
      pointerId?: number;
      isPrimary?: boolean;
    };
    if ('function' === typeof PointerEvent) {
      expect(down.pointerId).toBe(1);
      expect(down.isPrimary).toBe(true);
    }
  });
});
